function themeSvg(mode=state.themeMode){const system=currentDeviceKind?.()==="mobile"?'<svg class="theme-svg phone-theme-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="6.8" y="2.4" width="10.4" height="19.2" rx="3.6"/><path d="M10.1 5h3.8" stroke-width="2.2"/><path d="M9.3 8.4h5.4M9.3 11.1h4" opacity=".22"/><circle cx="12" cy="18.6" r=".75" fill="currentColor" stroke="none" opacity=".55"/></svg>':'<svg class="theme-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="5" width="16" height="11" rx="2.4"/><path d="M9 20h6M12 16v4"/><path d="M8.2 9.2h7.6M8.2 12.1h4.4" opacity=".32"/></svg>';const sun='<svg class="theme-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4.2"/><path d="M12 2.8v2.1M12 19.1v2.1M4.2 4.2l1.5 1.5M18.3 18.3l1.5 1.5M2.8 12h2.1M19.1 12h2.1M4.2 19.8l1.5-1.5M18.3 5.7l1.5-1.5"/></svg>';const moon='<svg class="theme-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19.2 15.2A8.2 8.2 0 0 1 8.8 4.8 8.6 8.6 0 1 0 19.2 15.2Z"/><path d="M15.8 5.2h.01M18.6 8.4h.01M13.4 8.2h.01"/></svg>';return mode==="system"?system:(mode==="dark"?moon:sun)}
function renderThemeButton(){const b=$("#themeToggle");if(!b)return;const label=state.themeMode==="system"?"\u8ddf\u968f\u7cfb\u7edf":(state.themeMode==="dark"?"\u6df1\u8272\u6a21\u5f0f":"\u6d45\u8272\u6a21\u5f0f");b.innerHTML=themeSvg(state.themeMode);b.dataset.mode=state.themeMode;b.title=`\u5f53\u524d\uff1a${label}\uff0c\u70b9\u51fb\u5207\u6362`;b.setAttribute("aria-label",`\u5f53\u524d\uff1a${label}\uff0c\u70b9\u51fb\u5207\u6362`)}
