async function saveSettings(){let ids=["install_prefix","network_name","default_reverse_ws_token","upload_dir","astrbot_plugin_dir","max_upload_mb","public_base_url","nailong_remote_server_url","nailong_remote_owner_ids","nailong_remote_bot_self_ids","nailong_remote_allowed_groups","nailong_remote_triggers","nailong_remote_qr_retry_seconds","nailong_remote_cooldown_seconds","theme_color","napcat_watchdog_interval","napcat_watchdog_abnormal_threshold","napcat_recovery_max","napcat_recovery_window","napcat_recovery_wait"];let body={};ids.forEach(k=>body[k]=$(`#set_${k}`).value);["max_upload_mb","napcat_watchdog_interval","napcat_watchdog_abnormal_threshold","napcat_recovery_max","napcat_recovery_window","napcat_recovery_wait","nailong_remote_qr_retry_seconds","nailong_remote_cooldown_seconds"].forEach(k=>body[k]=Number(body[k]));const sw=k=>$(`#set_${k}`)?.classList.contains("on");body.allow_dangerous=sw("allow_dangerous");body.napcat_watchdog_enabled=sw("napcat_watchdog_enabled");body.nailong_remote_login_enabled=sw("nailong_remote_login_enabled");for(const k of Object.keys(body))if(typeof body[k]==="number"&&!Number.isFinite(body[k]))return toast("\u8bf7\u586b\u5199\u6709\u6548\u6570\u5b57","error");await req("/api/settings",{method:"POST",body:JSON.stringify(body)});applyRuntimeConfig(body);invalidateCache("settings","watchdog");$("#setFoot")?.classList.remove("dirty");toast("\u8bbe\u7f6e\u5df2\u4fdd\u5b58\uff0cQQ \u8fdc\u7a0b\u767b\u5f55\u63d2\u4ef6\u914d\u7f6e\u5df2\u540c\u6b65")}
async function setupHttps(){const domain=$("#httpsDomain").value.trim(),email=$("#httpsEmail").value.trim();if(!domain)return toast("\u8bf7\u8f93\u5165\u57df\u540d");const t=await req("/api/https/setup",{method:"POST",body:JSON.stringify({domain,email})});toast("HTTPS \u914d\u7f6e\u4efb\u52a1\u5df2\u5f00\u59cb");showTask(t.id)}
async function restartWatchdog(){return withBusy("\u6b63\u5728\u91cd\u542f\u5b88\u62a4",async()=>{await req("/api/watchdog/restart",{method:"POST",body:"{}"});toast("NapCat \u81ea\u52a8\u6062\u590d\u5b88\u62a4\u5df2\u542f\u52a8");settings()})}
function visibleTasks(){return (state.tasks||[]).filter(t=>!["success","failed","cancelled"].includes(t.status)).slice(-6).reverse()}
const TASK_WATCH={};
function watchTask(id,opts={}){if(!id)return;if(TASK_WATCH[id]){Object.assign(TASK_WATCH[id],opts);return}const w=TASK_WATCH[id]=Object.assign({fails:0},opts);const tick=async()=>{if(TASK_WATCH[id]!==w)return;let t;try{t=await req(`/api/tasks/${encodeURIComponent(id)}`)}catch(e){if(++w.fails>8){delete TASK_WATCH[id];return}return setTimeout(tick,1500)}w.fails=0;try{w.onProgress?.(t)}catch{}if(["success","failed","cancelled"].includes(t.status)){delete TASK_WATCH[id];return taskSettled(t,w)}setTimeout(tick,document.hidden?3000:800)};setTimeout(tick,400)}
async function taskSettled(t,w={}){const ok=t.status==="success",kind=String(t.kind||"");if(w.napcat||/^(napcat|remote)/.test(kind))invalidateCache("dashboard","napcat","pool");else invalidateCache("dashboard","astrbot","plugins:astrbot","backup","files");try{w.onDone?.(t,ok)}catch(e){console.debug(e)}loadTasks();if(ok)toast(w.okText||`${t.title} 已完成`);else{toast(w.failText||`${t.title} 失败`,"error");if(state.taskModalId!==t.id&&$("#modal")?.classList.contains("hidden"))showTask(t.id)}await softRefreshPage()}
async function softRefreshPage(){const p=state.page;try{refresh(false);if(p==="napcat")return await napcat();if(p==="pool")return await pool();if(p==="files")return await refreshFiles();if(["astrbot","backup"].includes(p)&&$("#modal")?.classList.contains("hidden")&&!userEditingForm())return render()}catch(e){console.debug(e)}}
function taskPanel(){return `<div class="card span12 task-card task-floating task-hidden"><div class="task-head"><div><h3>\u4efb\u52a1\u8fdb\u5ea6</h3><p class="muted">\u6b63\u5728\u5904\u7406\u7684\u4efb\u52a1\u4f1a\u56fa\u5b9a\u5728\u8fd9\u91cc\u3002</p></div></div><div id="tasks" class="file-cards task-list"></div></div>`}
async function loadTasks(){try{state.tasks=await req("/api/tasks");const el=$("#tasks");if(!el)return;const rows=visibleTasks(),card=el.closest(".task-card"),sig=rows.map(t=>`${t.id}:${t.status}:${t.progress}`).join("|");card?.classList.toggle("task-hidden",!rows.length);if(el.dataset.renderSig===sig)return;state.tasksRenderSig=sig;el.dataset.renderSig=sig;el.innerHTML=rows.map(t=>`<div class="file-card task-item" data-task-id="${q(t.id)}"><div><b>${safeText(t.title)}</b><div class="muted">${taskStatusText(t.status)} / ${safeText(t.updated_at)}</div><div class="progress"><span style="width:${t.progress}%"></span></div></div><button class="tiny" onclick="showTask('${q(t.id)}')">查看</button></div>`).join("")}catch{}}
async function showTask(id){state.taskModalId=id;watchTask(id);const draw=async()=>{const t=await req(`/api/tasks/${id}`);const html=`<div id="taskModalInner" class="task-modal"><h3 id="taskTitle">${safeText(t.title)}</h3><p id="taskMeta" class="muted">\u72b6\u6001: ${taskStatusText(t.status)} / \u8fdb\u5ea6: ${t.progress}%</p><div class="progress"><span id="taskProgress" style="width:${t.progress}%"></span></div><pre id="taskLog" class="code">${esc((t.logs||[]).join("\n"))}</pre></div>`;if($("#modal")?.classList.contains("hidden")||state.taskModalId!==id||!$("#taskModalInner")){openModal(html,()=>closeModal(),{confirmText:"\u786e\u5b9a",cancelText:"\u53d6\u6d88"})}else{$("#taskTitle").textContent=t.title;$("#taskMeta").textContent=`\u72b6\u6001: ${taskStatusText(t.status)} / \u8fdb\u5ea6: ${t.progress}%`;$("#taskProgress").style.width=t.progress+"%";$("#taskLog").textContent=(t.logs||[]).join("\n")}const done=t.status==="success"||t.status==="failed";const ok=$("#modalOk");if(ok&&$("#taskModalInner")){ok.style.display="";ok.textContent=done?"\u5b8c\u6210":"\u786e\u5b9a";ok.className="primary";ok.onclick=()=>closeModal()}const cancel=$("#modal .modal-actions button:first-child");if(cancel&&$("#taskModalInner"))cancel.textContent=done?"\u5173\u95ed":"\u53d6\u6d88";const box=$("#taskLog");if(box)box.scrollTop=box.scrollHeight;if(t.status==="success"||t.status==="failed"||t.status==="cancelled")return true;return false};if(await draw())return;const timer=setInterval(async()=>{try{if($("#modal")?.classList.contains("hidden")||state.taskModalId!==id){clearInterval(timer);return}if(await draw())clearInterval(timer)}catch{clearInterval(timer)}},1200)}
function openModal(html,ok,options={}){$("#modalBody").innerHTML=html;const m=$("#modal");m.classList.remove("closing");{const card=m.querySelector(".modal-card");card?.classList.remove("sheet","qr-mode");card?.classList.toggle("alert",!!$("#modalBody .confirm-box"))}const okBtn=$("#modalOk"),cancel=$("#modal .modal-actions button:first-child");if(okBtn){okBtn.textContent=options.confirmText||"\u786e\u5b9a";okBtn.className=options.confirmClass||"primary";okBtn.disabled=false}if(cancel){cancel.textContent=options.cancelText||"\u53d6\u6d88";cancel.disabled=false}clearTimeout(closeModal._t);if(!state.modalLocked){state.modalLocked=true;lockScroll()}m.classList.remove("hidden");requestAnimationFrame(()=>m.classList.add("show"));okBtn.style.display=ok?"":"none";okBtn.onclick=ok?async()=>{if(okBtn.disabled)return;const old=okBtn.innerHTML;try{okBtn.disabled=true;if(cancel)cancel.disabled=true;okBtn.classList.add("is-busy");okBtn.innerHTML=`<span class="spin"></span>${options.loadingText||"\u5904\u7406\u4e2d"}`;await ok()}catch(e){toast(e.message||"\u64cd\u4f5c\u5931\u8d25");okBtn.disabled=false;if(cancel)cancel.disabled=false;okBtn.classList.remove("is-busy");okBtn.innerHTML=old}}:(()=>{})}

function closeModal(){state.taskModalId=null;if(state.qrTimer){clearTimeout(state.qrTimer);clearInterval(state.qrTimer);state.qrTimer=null}const m=$("#modal");m.classList.add("closing");m.classList.remove("show");clearTimeout(closeModal._t);closeModal._t=setTimeout(()=>{m.classList.add("hidden");m.classList.remove("closing")},220);if(state.modalLocked){state.modalLocked=false;unlockScroll()}}
function confirmDanger({title="\u786e\u8ba4\u6267\u884c\u64cd\u4f5c\uff1f",name="",message="",confirmText="\u786e\u8ba4",cancelText="\u53d6\u6d88",onConfirm}){openModal(`<div class="confirm-box"><div class="confirm-icon">!</div><div><h3>${safeText(title)}</h3><p class="muted">${safeText(message)}</p>${name?`<div class="confirm-target"><span>\u5b9e\u4f8b\u540d\u79f0</span><b>${safeText(name)}</b></div>`:""}</div></div>`,async()=>{closeModal();await onConfirm?.()},{confirmText,cancelText,confirmClass:"danger"})}
function confirmDo(msg,word,fn){openModal(`<div class="confirm-box"><div class="confirm-icon">!</div><div><h3>\u4e8c\u6b21\u786e\u8ba4</h3><p class="muted">${safeText(msg)}</p><input id="confirmInput" class="confirm-input" placeholder="${q(word)}"></div></div>`,async()=>{if($("#confirmInput").value!==word)return toast("\u786e\u8ba4\u6587\u5b57\u4e0d\u5339\u914d");closeModal();await fn()},{confirmClass:"danger"})}
function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[m]))}

function jsq(s){return String(s??"").replace(/\\/g,"\\\\").replace(/'/g,"\\'").replace(/[\r\n]+/g," ")}
function q(s){return esc(jsq(s))}
function safeHref(u){try{const x=new URL(String(u||""),location.href);return ["http:","https:"].includes(x.protocol)?esc(x.href):"#"}catch{return "#"}}
function safeText(s){return esc(s)}

function deviceLabel(){const d=state.device||detectDevice(),sys=d.system||{},br=d.browser||{},dev=d.device||{};const system=sys.ipadOS?"iPadOS":sys.ios?"iOS":sys.android?"Android":sys.windows?"Windows":sys.macos?"macOS":sys.linux?"Linux":"Unknown";const browser=br.wechat?"\u5fae\u4fe1\u6d4f\u89c8\u5668":br.qq?"QQ \u6d4f\u89c8\u5668":br.quark?"\u5938\u514b":br.uc?"UC \u6d4f\u89c8\u5668":br.edge?"Edge":br.firefox?"Firefox":br.chrome?"Chrome":br.safari?"Safari":"Unknown";const type=dev.mobile?"\u624b\u673a":dev.tablet?"\u5e73\u677f":"\u684c\u9762\u7aef";return {system,browser,type}}
function deviceIconSvg(kind){const desktop='<svg class="device-svg desktop" viewBox="0 0 64 64" fill="none" aria-hidden="true"><rect x="10" y="12" width="44" height="30" rx="5.5" stroke="currentColor" stroke-width="3.2"/><path d="M24 51h16M32 42v9" stroke="currentColor" stroke-width="3.2" stroke-linecap="round"/><path d="M17 19h30M17 25h18" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" opacity=".34"/></svg>';const phone='<svg class="device-svg phone" viewBox="0 0 64 64" fill="none" aria-hidden="true"><rect x="20" y="5" width="24" height="54" rx="9" stroke="currentColor" stroke-width="3.2"/><path d="M29 10h6" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" opacity=".52"/><circle cx="32" cy="53" r="1.6" fill="currentColor" opacity=".65"/><path d="M25.5 17.5h13M25.5 22.5h8" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" opacity=".28"/><circle cx="39.5" cy="13" r="1.1" fill="currentColor" opacity=".45"/></svg>';return kind==="mobile"?phone:desktop}
function currentDeviceKind(){const d=state.device||detectDevice(),dev=d.device||{};return dev.mobile?"mobile":"desktop"}
function deviceInfoForCopy(){applyDeviceClasses();const d=state.device||detectDevice(),l=deviceLabel();return {time:new Date().toISOString(),system:l.system,browser:l.browser,device_type:l.type,screen:d.screen,capabilities:d.capabilities,raw:d.raw,classes:[...document.documentElement.classList].filter(x=>/^(os-|browser-|device-|touch-device|small-screen|landscape|portrait|ios-|ipad-|standalone)/.test(x))}}
function renderDeviceCard(){try{const sec=$("#content section.grid");if(!sec||$("#deviceInfoCard"))return;const d=state.device||detectDevice(),l=deviceLabel(),kind=currentDeviceKind(),deviceName=kind==="mobile"?(l.system==="iOS"?"iPhone 17 Pro Max":"\u624b\u673a\u7aef"):"\u7535\u8111\u7aef";const html=`<div id="deviceInfoCard" class="card span12 device-info-card"><div class="section-head device-head"><div class="device-head-main"><div class="device-hero ${kind}">${deviceIconSvg(kind)}</div><div><h3>\u8bbe\u5907\u73af\u5883\u68c0\u6d4b</h3><p class="muted"><b>${safeText(deviceName)}</b> / \u4ec5\u7528\u4e8e iOS Safari \u517c\u5bb9\u5224\u65ad\u548c\u95ee\u9898\u6392\u67e5\uff0c\u4e0d\u751f\u6210\u552f\u4e00\u8bbe\u5907 ID\u3002</p></div></div><button class="soft" onclick="copyDeviceInfo()">\u590d\u5236\u8bbe\u5907\u4fe1\u606f</button></div><div class="device-grid"><div><b>\u7cfb\u7edf</b><span>${safeText(l.system)}</span></div><div><b>\u6d4f\u89c8\u5668</b><span>${safeText(l.browser)}</span></div><div><b>\u8bbe\u5907\u7c7b\u578b</b><span>${safeText(l.type)}</span></div><div><b>\u5c4f\u5e55</b><span>${d.screen.width} x ${d.screen.height}</span></div><div><b>\u7a97\u53e3</b><span>${d.screen.innerWidth} x ${d.screen.innerHeight}</span></div><div><b>DPR</b><span>${d.screen.dpr}</span></div><div><b>\u6700\u5927\u89e6\u6478\u70b9</b><span>${d.raw.maxTouchPoints||0}</span></div><div><b>iOS Safari</b><span>${d.system.ios&&d.browser.safari?"\u662f":"\u5426"}</span></div><div><b>iPadOS</b><span>${d.system.ipadOS?"\u662f":"\u5426"}</span></div><div><b>PWA</b><span>${d.capabilities.standalone?"\u662f":"\u5426"}</span></div><div><b>\u526a\u8d34\u677f</b><span>${d.capabilities.clipboard?"\u652f\u6301":"\u964d\u7ea7\u652f\u6301"}</span></div><div><b>\u6bdb\u73bb\u7483</b><span>${d.capabilities.backdropFilter?"\u652f\u6301":"\u4e0d\u652f\u6301"}</span></div></div><details class="ua-details"><summary>User-Agent</summary><pre class="code selectable">${esc(d.raw.userAgent||"")}</pre></details></div>`;sec.insertAdjacentHTML("beforeend",html)}catch(e){console.debug(e)}}
async function copyDeviceInfo(){await copyText(JSON.stringify(deviceInfoForCopy(),null,2))}
async function reportDeviceInfo(){try{const d=deviceInfoForCopy();await req("/api/device/report",{method:"POST",body:JSON.stringify({system:d.system,browser:d.browser,device_type:d.device_type,screen:`${d.screen.width}x${d.screen.height}`,viewport:`${d.screen.innerWidth}x${d.screen.innerHeight}`,dpr:d.screen.dpr,user_agent:d.raw.userAgent})})}catch{}}

