req("/api/me").then(d=>{applyRuntimeConfig(d.config||{});state.user="\u5df2\u767b\u5f55";$("#login").classList.add("hidden");$("#app").classList.remove("hidden");init()}).catch(()=>{try{if(sessionStorage.passwordChangedHint)$("#loginMsg").textContent="\u5bc6\u7801\u5df2\u4fee\u6539\uff0c\u6240\u6709\u8bbe\u5907\u5df2\u9000\u51fa\u767b\u5f55\uff0c\u8bf7\u91cd\u65b0\u767b\u5f55\u3002"}catch{}})
